From 011571e240c722b13d0f268ce5e236f860c55835 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:00:39 +0100
Subject: [PATCH] session-restore: also save applications that only have a tray
 icon

Applications whose only interface is a tray icon have no window, so the
saved session never listed them and they were not started again. Also
save the owners of registered tray items, found by their command line.

BUG: 525807
---
 startkde/session-restore/CMakeLists.txt |  1 +
 startkde/session-restore/save.cpp       | 68 +++++++++++++++++++++++--
 2 files changed, 64 insertions(+), 5 deletions(-)

diff --git a/startkde/session-restore/CMakeLists.txt b/startkde/session-restore/CMakeLists.txt
index d454251345..88a60b591f 100644
--- a/startkde/session-restore/CMakeLists.txt
+++ b/startkde/session-restore/CMakeLists.txt
@@ -10,6 +10,7 @@ add_executable(plasma-fallback-session-save
 )
 target_link_libraries(plasma-fallback-session-save
     Qt6::Core
+    Qt6::DBus
     KF6::KIOGui
     KF6::ConfigCore
     PW::LibTaskManager
diff --git a/startkde/session-restore/save.cpp b/startkde/session-restore/save.cpp
index 7cd20f4cf0..5fe935e0a5 100644
--- a/startkde/session-restore/save.cpp
+++ b/startkde/session-restore/save.cpp
@@ -5,9 +5,16 @@
 SPDX-License-Identifier: LGPL-2.1-or-later
 */

+#include <algorithm>
 #include <chrono>

+#include <QDBusConnection>
+#include <QDBusConnectionInterface>
+#include <QDBusMessage>
+#include <QDBusReply>
+#include <QDBusVariant>
 #include <QEventLoop>
+#include <QFile>
 #include <QGuiApplication>
 #include <QRegularExpression>
 #include <QThreadPool>
@@ -21,7 +28,9 @@ SPDX-License-Identifier: LGPL-2.1-or-later
 #include <abstracttasksmodel.h>
 #include <windowtasksmodel.h>

+#include <KApplicationTrader>
 #include <KConfigGroup>
+#include <KIO/DesktopExecParser>
 #include <KSharedConfig>

 #include "debug.h"
@@ -55,6 +64,12 @@ int main(int argc, char *argv[])
         config->deleteGroup(group);
     }

+    const QStringList excludeApps = [] {
+        KSharedConfig::Ptr config = KSharedConfig::openConfig(u"ksmserverrc"_s);
+        KConfigGroup generalGroup(config, u"General"_s);
+        return generalGroup.readEntry("excludeApps").split(QRegularExpression(u"[,:]"_s), Qt::SkipEmptyParts);
+    }();
+
     QSet<QString> seenAppIds;
     for (int i = 0; i < tasksModel.rowCount(); ++i) {
         const QModelIndex index = tasksModel.index(i, 0);
@@ -70,11 +85,6 @@ int main(int argc, char *argv[])
             continue;
         }

-        static const auto excludeApps = []() -> QStringList {
-            KSharedConfig::Ptr config = KSharedConfig::openConfig(u"ksmserverrc"_s);
-            KConfigGroup generalGroup(config, u"General"_s);
-            return generalGroup.readEntry("excludeApps").split(QRegularExpression(u"[,:]"_s), Qt::SkipEmptyParts);
-        }();
         if (excludeApps.contains(appId)) {
             qCDebug(FALLBACK_SESSION_RESTORE) << "Excluding" << appId;
             continue;
@@ -86,6 +96,54 @@ int main(int argc, char *argv[])
         seenAppIds.insert(appId);
     }

+    // Applications that only show a tray icon have no window, so also save the
+    // applications owning a StatusNotifierItem, matched by their command line
+    QDBusMessage message =
+        QDBusMessage::createMethodCall(u"org.kde.StatusNotifierWatcher"_s, u"/StatusNotifierWatcher"_s, u"org.freedesktop.DBus.Properties"_s, u"Get"_s);
+    message << u"org.kde.StatusNotifierWatcher"_s << u"RegisteredStatusNotifierItems"_s;
+    const QDBusMessage reply = QDBusConnection::sessionBus().call(message);
+    const QStringList notifierItems =
+        reply.type() == QDBusMessage::ReplyMessage ? reply.arguments().value(0).value<QDBusVariant>().variant().toStringList() : QStringList();
+
+    int groupIndex = tasksModel.rowCount();
+    for (const QString &notifierItem : notifierItems) {
+        // Items are registered as "<service><object path>"
+        const QDBusReply<uint> pid = QDBusConnection::sessionBus().interface()->servicePid(notifierItem.section(u'/', 0, 0));
+        if (!pid.isValid()) {
+            continue;
+        }
+        QFile cmdlineFile(u"/proc/%1/cmdline"_s.arg(pid.value()));
+        if (!cmdlineFile.open(QIODevice::ReadOnly)) {
+            continue;
+        }
+        QStringList arguments;
+        for (const QByteArray &argument : cmdlineFile.readAll().split('\0')) {
+            arguments << QString::fromLocal8Bit(argument);
+        }
+
+        // Compare whole arguments, so that scripts run by an interpreter are found too
+        const KService::List services = KApplicationTrader::query([&arguments](const KService::Ptr &service) {
+            const QString binary = KIO::DesktopExecParser::executablePath(service->exec());
+            return !service->noDisplay() && !binary.isEmpty() && std::ranges::any_of(arguments, [&binary](const QString &argument) {
+                return argument == binary || argument.endsWith(u'/' + binary);
+            });
+        });
+        if (services.isEmpty()) {
+            qCDebug(FALLBACK_SESSION_RESTORE) << "No application found for tray item" << notifierItem << arguments;
+            continue;
+        }
+
+        const QString appId = services.constFirst()->storageId();
+        if (seenAppIds.contains(appId) || excludeApps.contains(appId)) {
+            continue;
+        }
+
+        auto group = config->group(QString::number(groupIndex++));
+        qCDebug(FALLBACK_SESSION_RESTORE) << "Saving tray-only application" << group.name() << appId;
+        group.writeEntry("appId", appId);
+        seenAppIds.insert(appId);
+    }
+
     config->sync();

     // WaylandtasksModels runs threads to fetch icons, prevent crashes when they construct QPixmaps but the QGuiApp is already gone
-- 
